/**
 * Program proposal (SPEC §5.1, §5.2). Pure: given the event time, "now" and the athlete's training days it
 * returns the planned items. Training items become sessions only when the athlete taps them; night-before
 * and primer items are generated by the scheduler at event start minus 72 hours.
 */
import { localDateIn, zonedLocalToUtc } from '@avanvu/core';

export type ProgramKind = 'training' | 'night_before' | 'primer' | 'debrief';

export interface PlannedItem {
  kind: ProgramKind;
  /** Local calendar date in the event's time zone, YYYY-MM-DD. */
  target_date: string;
  /** Null for training and debrief items. */
  generate_at: Date | null;
}

export interface ProgramInput {
  startsAt: Date;
  timeZone: string;
  now: Date;
  /** 0 = Sunday. Default Tuesday and Saturday. */
  trainingDays?: readonly number[];
}

const DAY_MS = 86_400_000;
export const SPECIAL_LEAD_MS = 72 * 3_600_000;
export const DEFAULT_TRAINING_DAYS = [2, 6] as const;

const addDays = (isoDate: string, n: number): string => {
  const d = new Date(`${isoDate}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() + n);
  return d.toISOString().slice(0, 10);
};
const weekday = (isoDate: string): number => new Date(`${isoDate}T00:00:00Z`).getUTCDay();
const daysBetween = (a: string, b: string): number =>
  Math.round((new Date(`${b}T00:00:00Z`).getTime() - new Date(`${a}T00:00:00Z`).getTime()) / DAY_MS);

/** Evenly spread `count` dates across [from, to] inclusive. */
function spread(from: string, to: string, count: number): string[] {
  const span = daysBetween(from, to);
  if (span < 0 || count <= 0) return [];
  const n = Math.min(count, span + 1);
  const out = new Set<string>();
  for (let i = 0; i < n; i++)
    out.add(addDays(from, n === 1 ? Math.floor(span / 2) : Math.round((span * i) / (n - 1))));
  return [...out].sort();
}

export function planProgram(input: ProgramInput): PlannedItem[] {
  const { startsAt, timeZone, now } = input;
  const trainingDays = input.trainingDays?.length ? input.trainingDays : DEFAULT_TRAINING_DAYS;
  const eventDate = localDateIn(startsAt, timeZone);
  const today = localDateIn(now, timeZone);
  const daysAway = Math.floor((startsAt.getTime() - now.getTime()) / DAY_MS);
  const items: PlannedItem[] = [];

  // Training sessions sit from tomorrow up to three days before the event, clear of the special sessions.
  const firstTraining = addDays(today, 1);
  const lastTraining = addDays(eventDate, -3);
  let training: string[] = [];
  if (daysAway >= 21) {
    for (let d = firstTraining; daysBetween(d, lastTraining) >= 0; d = addDays(d, 1)) {
      if (trainingDays.includes(weekday(d))) training.push(d);
    }
  } else if (daysAway >= 7) {
    training = spread(firstTraining, lastTraining, Math.min(4, Math.max(2, Math.round(daysAway / 4))));
  } else if (daysAway >= 2) {
    training = spread(firstTraining, lastTraining, daysAway >= 4 ? 2 : 1);
  }
  for (const d of training) items.push({ kind: 'training', target_date: d, generate_at: null });

  const generateAt = new Date(Math.max(startsAt.getTime() - SPECIAL_LEAD_MS, now.getTime()));
  // Night before: kept while the evening before has not passed (22:00 local the day before the event).
  const eveningBefore = zonedLocalToUtc(`${addDays(eventDate, -1)}T22:00`, timeZone);
  if (now < eveningBefore) {
    items.push({ kind: 'night_before', target_date: addDays(eventDate, -1), generate_at: generateAt });
  }
  if (now < startsAt) items.push({ kind: 'primer', target_date: eventDate, generate_at: generateAt });
  items.push({ kind: 'debrief', target_date: addDays(eventDate, 1), generate_at: null });
  return items;
}

/** Event edits that change date, time or zone recompute `generate_at` for items not yet generated. */
export function recomputeGenerateAt(kind: ProgramKind, startsAt: Date, now: Date): Date | null {
  if (kind !== 'night_before' && kind !== 'primer') return null;
  return new Date(Math.max(startsAt.getTime() - SPECIAL_LEAD_MS, now.getTime()));
}
